# ---- RUTINA: print_str (Escribe en TTY Logisim 0xff000004) ----
__print_str:
    li t1, 0xff000004
.print_loop:
    lb t0, 0(a0)
    beqz t0, .print_end
    add zero, zero, t0 # FIX: Estabilizar rs2 para Logisim TTY
    sw t0, 0(t1)
    addi a0, a0, 1
    j .print_loop
.print_end:
    ret

# ---- RUTINA: soft_mul (Multiplicador de software) ----
__soft_mul:
    li t0, 0
    li t1, 0
.mul_loop:
    beq t1, a1, .mul_end
    add t0, t0, a0
    addi t1, t1, 1
    j .mul_loop
.mul_end:
    mv a0, t0
    ret

# ---- RUTINA: print_num (Imprime un entero a ASCII en TTY) ----
__print_num:
    addi sp, sp, -32
    sw ra, 28(sp)
    sw s0, 24(sp)
    sw s1, 20(sp)
    mv s0, a0
    li s1, 0xff000004
    bnez s0, .L_num_loop_prep
    li t0, 48
    add zero, zero, t0
    sw t0, 0(s1)
    j .L_num_end
.L_num_loop_prep:
    mv t3, sp
.L_num_loop:
    beqz s0, .L_num_print
    mv t1, s0
    li t2, 0
.L_div10:
    li t4, 10
    blt t1, t4, .L_div10_end
    sub t1, t1, t4
    addi t2, t2, 1
    j .L_div10
.L_div10_end:
    addi t1, t1, 48
    sb t1, 0(t3)
    addi t3, t3, 1
    mv s0, t2
    j .L_num_loop
.L_num_print:
.L_num_print_loop:
    addi t3, t3, -1
    lb t0, 0(t3)
    add zero, zero, t0
    sw t0, 0(s1)
    bne t3, sp, .L_num_print_loop
.L_num_end:
    lw ra, 28(sp)
    lw s0, 24(sp)
    lw s1, 20(sp)
    addi sp, sp, 32
    ret

